<script setup lang="ts">
import GatewayManager from './GatewayManager.vue'
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue'
import ProtocolLayers from './ProtocolLayers.vue'
import NetworkFields from './NetworkFields.vue'
import ProtocolBatch from './ProtocolBatch.vue'
type Row=Record<string,any>
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>,hosts:Row[],initialHost?:string,toolsOnly?:boolean}>()
const emit=defineEmits(['changed'])
const services=ref<Row[]>([]),nodes=ref<Row[]>([]),templates=ref<Row[]>([]),certificates=ref<Row[]>([]),proxies=ref<Row[]>([]),catalog=ref<Row[]>([])
const sniPresets=[{name:'微软 · Microsoft',host:'www.microsoft.com'},{name:'苹果 · Apple',host:'www.apple.com'},{name:'Cloudflare',host:'www.cloudflare.com'}]
function chooseSNI(host:string){if(!host)return;form.value.reality.target=host;form.value.reality.port=443;form.value.server_name=host}
const nodeView=ref('inbounds'),showBatch=ref(false),batchHost=ref(''),batchEngine=ref('sing-box')
function batch(host='',engine='sing-box'){batchHost.value=host||hostFilter.value;batchEngine.value=engine;showBatch.value=true}
async function batchSaved(){showBatch.value=false;notice.value='所选协议已原子保存。请分配用户组，按需要启用并等待 Agent 回报。';await action(reload);emit('changed')}
const kernels=ref<Row[]>([]),kernelPreview=ref<Row|null>(null)
async function showKernel(host:string,engine:string){await action(async()=>{kernelPreview.value=await props.api('hosts/'+host+'/kernel-config?engine='+engine)})}
function createOn(host:string,engine:string){batch(host,engine)}
const tab=ref(props.toolsOnly?'certificates':'nodes'),hostFilter=ref(props.initialHost??''),busy=ref(false),error=ref(''),notice=ref(''),editing=ref(''),preview=ref<any>(null),confirm=ref<Row|null>(null)
const fresh=()=>({endpoint_addresses:[] as string[],egress_families:[] as string[],clear_hy2_obfs:false,clear_hysteria_obfs:false,hysteria_obfs_password:'',listen_network:'',cipher:'',snell_version:0,snell_obfs:'',snell_host:'',snell_mode:'',hy2_obfs_password:'',up_mbps:0,down_mbps:0,reality:{target:'',port:443,short_id:'',fingerprint:'chrome',public_key:''},flow:'',alpn:[] as string[],congestion:'',ws_host:'',service_name:'',managed_users:true,password:'',username:'',uuid:'',name:'',host_id:'',node_id:'',engine:'sing-box',kind:'vless',address:'',listen:'0.0.0.0',port:2080,transport:'tcp',path:'',tls_mode:'reality',server_name:'',certificate_id:'',certificate:'',private_key:'',next_id:'',parent_id:'',tunnels:[] as Row[],version:0,rotate_credentials:false})
const form=ref(fresh()),showForm=ref(false)
const certForm=ref({id:'',domain:'',email:'',provider:'http-01',dns_token:'',certificate:'',private_key:''})
const reverseForm=ref({id:'',domain:'',upstream:'http://127.0.0.1:3000',certificate_id:'',enabled:false,version:0})
const compatible=computed(()=>templates.value.filter(t=>t.engines?.includes(form.value.engine)))
const activeTemplate=computed(()=>templates.value.find(t=>t.kind===form.value.kind))
const isReality=computed(()=>['vless','trojan','vmess'].includes(form.value.kind)&&form.value.tls_mode==='reality')
const needsTLS=computed(()=>activeTemplate.value?.certificate&&form.value.tls_mode==='tls')
const alpnText=computed({get:()=>form.value.alpn.join(','),set:v=>{form.value.alpn=v.split(',').map(s=>s.trim()).filter(Boolean)}})
const websocket=computed(()=>['vless','vmess','trojan'].includes(form.value.kind))
const filtered=computed(()=>services.value.filter(s=>!hostFilter.value||s.host_id===hostFilter.value))
const hops=computed(()=>services.value.filter(s=>!s.delete_requested_at&&s.id!==editing.value&&!['frps','frpc','naive'].includes(s.kind)&&(form.value.engine!=='xray'||['shadowsocks','vless','vmess','trojan','http','socks'].includes(s.kind))))
let hydrating=false
let alive=true,timer:ReturnType<typeof setTimeout>
onUnmounted(()=>{alive=false;clearTimeout(timer);form.value.private_key='';certForm.value.dns_token=''})
async function action(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){if(alive)error.value=String(e)}finally{if(alive)busy.value=false}}
let loaded=false
async function reload(){
 if(!loaded){const data=await Promise.all(['live','protocol-templates','certificates','reverse-proxies','engine-catalog'].map(p=>props.api(p)));if(!alive)return;[services.value,templates.value,certificates.value,proxies.value,catalog.value]=data;loaded=true}
 else if(props.toolsOnly){const data=await Promise.all(['certificates','reverse-proxies'].map(p=>props.api(p)));if(!alive)return;[certificates.value,proxies.value]=data}
 else{const data=await props.api('live');if(!alive)return;services.value=data}
 if(!props.toolsOnly){const rows=await Promise.all(props.hosts.filter(h=>!hostFilter.value||h.id===hostFilter.value).map(async h=>(await props.api('hosts/'+h.id+'/kernels')).map((k:Row)=>({...k,host_id:h.id}))));if(alive)kernels.value=rows.flat()}
}
watch(hostFilter,()=>{void action(reload)})
function schedule(){timer=setTimeout(async()=>{if(document.visibilityState!=='hidden'&&!busy.value&&!showForm.value)await action(reload);if(alive)schedule()},30000)}
onMounted(()=>{void action(reload);schedule()})
watch(()=>form.value.engine,()=>{if(hydrating)return;if(!compatible.value.some(t=>t.kind===form.value.kind)&&form.value.engine!=='frp')form.value.kind=compatible.value[0]?.kind??'shadowsocks';if(form.value.engine==='frp')form.value.kind='frps';form.value.node_id=''})
watch(()=>form.value.kind,()=>{if(hydrating)return;form.value.transport='tcp';form.value.path='';form.value.tls_mode='tls';form.value.certificate='';form.value.private_key='';form.value.certificate_id='';form.value.server_name='';form.value.username='';form.value.next_id='';form.value.flow='';form.value.ws_host='';form.value.service_name='';form.value.congestion='';form.value.alpn=[];form.value.cipher='';form.value.listen_network='';form.value.snell_version=0;form.value.snell_obfs='';form.value.snell_host='';form.value.snell_mode='';form.value.hy2_obfs_password='';form.value.hysteria_obfs_password='';form.value.clear_hysteria_obfs=false;form.value.up_mbps=0;form.value.down_mbps=0;form.value.managed_users=!['shadowsocks','snell','frps','frpc'].includes(form.value.kind)})
watch(()=>form.value.parent_id,async id=>{if(hydrating||editing.value||form.value.kind!=='frpc'||!id)return;try{const detail=await props.api('live/'+id);if(form.value.parent_id===id)form.value.tunnels=(detail.spec.tunnels??[]).map((t:Row)=>({...t,type:t.type||'tcp'}))}catch(e){error.value=String(e)}})
watch(()=>form.value.tls_mode,()=>{if(hydrating)return;if(!isReality.value)form.value.flow='';if(isReality.value){if(!['tcp','grpc','xhttp'].includes(form.value.transport))form.value.transport='tcp';form.value.certificate_id='';form.value.flow=form.value.kind==='vless'&&form.value.transport==='tcp'?'xtls-rprx-vision':''}})
watch(()=>form.value.certificate_id,id=>{const c=certificates.value.find(c=>c.id===id);if(c)form.value.server_name=c.domain})
watch(()=>form.value.transport,value=>{if(hydrating)return;if(!['ws','http','httpupgrade','xhttp'].includes(value)){form.value.path='';form.value.ws_host=''};if(value!=='grpc')form.value.service_name='';if(value!=='tcp')form.value.flow=''})
async function create(){hydrating=true;editing.value='';form.value=fresh();form.value.host_id=hostFilter.value||props.hosts.find(h=>h.online)?.id||props.hosts[0]?.id||'';form.value.address=props.hosts.find(h=>h.id===form.value.host_id)?.address??'';preview.value=null;await nextTick();hydrating=false;showForm.value=true}
async function edit(row:Row){await action(async()=>{const detail=await props.api('live/'+row.id);hydrating=true;editing.value=row.id;form.value={...fresh(),...detail.spec,managed_users:!!detail.spec.managed_users,hy2_obfs_password:'',password:'',uuid:'',name:detail.name,host_id:detail.host_id,node_id:detail.node_id,certificate_id:detail.certificate_id,next_id:detail.next_id,parent_id:detail.parent_id??'',version:detail.version,engine:['frps','frpc'].includes(detail.spec.kind)?'frp':detail.spec.engine||'sing-box',transport:detail.spec.transport||'tcp',tls_mode:detail.spec.tls_mode||'tls',certificate:'',private_key:'',rotate_credentials:false};preview.value=detail.rendered;await nextTick();hydrating=false;showForm.value=true})}
function save(){void action(async()=>{const fields=['listen_network','endpoint_addresses','egress_families','clear_hy2_obfs','clear_hysteria_obfs','hysteria_obfs_password','cipher','snell_version','snell_obfs','snell_host','snell_mode','hy2_obfs_password','up_mbps','down_mbps','reality','flow','alpn','congestion','ws_host','service_name','managed_users','password','username','uuid','name','host_id','node_id','engine','kind','address','listen','port','transport','path','tls_mode','server_name','certificate_id','certificate','private_key','next_id','parent_id','tunnels'];if(editing.value)fields.push('version','rotate_credentials');const payload=Object.fromEntries(fields.map(k=>[k,(form.value as Row)[k]]));if(form.value.engine==='frp'){delete payload.engine;payload.transport='';payload.tls_mode=''};if(!isReality.value)payload.reality=null;if(!needsTLS.value){if(!isReality.value)payload.server_name='';payload.certificate='';payload.private_key='';payload.certificate_id='';if(!isReality.value&&form.value.kind!=='vmess')payload.tls_mode=''};await props.api('live'+(editing.value?'/'+editing.value:''),editing.value?'PUT':'POST',payload);form.value.private_key='';form.value.certificate='';form.value.password='';form.value.uuid='';form.value.hy2_obfs_password='';showForm.value=false;await reload();emit('changed');notice.value=editing.value?'配置版本已保存，等待 Agent 原生检查与回报':'协议配置已保存。可在列表启用，Agent 会统一下发该 VPS 的内核配置。'})}
watch(()=>form.value.host_id,id=>{if(!editing.value){form.value.address=props.hosts.find(h=>h.id===id)?.address??'';form.value.endpoint_addresses=[];form.value.egress_families=[]}})
function remove(row:Row){confirm.value={...row,operation:'delete'}}
function toggle(row:Row){confirm.value={...row,operation:'toggle'}}
function requestCert(){confirm.value={operation:'certificate',name:certForm.value.domain}}
function saveReverse(){confirm.value={operation:'reverse',name:reverseForm.value.domain}}
function confirmAction(){const c=confirm.value;if(!c)return;confirm.value=null;void action(async()=>{if(c.operation==='delete'){const r=await props.api('live/'+c.id,'DELETE');notice.value=r.pending_stop?'正在删除：等待 Agent 停止回执后自动移除并释放端口。':'协议配置已删除，关联权限与订阅已移除。'}if(c.operation==='toggle')await props.api('live/'+c.id+'/toggle','POST',{enabled:!c.enabled});if(c.operation==='certificate'){const {id,...payload}=certForm.value;await props.api('certificates'+(id?'/'+id:''),id?'PUT':'POST',payload);certForm.value.dns_token='';certForm.value.private_key='';certForm.value.certificate='';notice.value=certForm.value.provider==='manual'?'手动证书已登记；绑定节点将接收更新版本':'证书请求已排队；HTTP-01 需要域名指向总管理网关且 80 端口可达。后台负责自动续期。'}if(c.operation==='reverse'){const {id,...payload}=reverseForm.value;await props.api('reverse-proxies'+(id?'/'+id:''),id?'PUT':'POST',payload);notice.value='反代设置已保存，等待网关检查并回报'}await reload();emit('changed')})}
function editCertificate(c:Row){certForm.value={id:c.id,domain:c.domain,email:'',provider:'manual',dns_token:'',certificate:'',private_key:''}}
function retry(c:Row){void action(async()=>{await props.api('certificates/'+c.id+'/retry','POST',{});await reload()})}
function editReverse(row:Row){reverseForm.value={id:row.id,domain:row.domain,upstream:row.upstream,certificate_id:row.certificate_id,enabled:row.enabled,version:row.version}}
function hostName(id:string){return props.hosts.find(h=>h.id===id)?.name??id.slice(0,8)}
function chain(row:Row){const names=[row.name],seen=new Set([row.id]);let next=row.next_id;while(next&&names.length<8){const n=services.value.find(s=>s.id===next);if(!n||seen.has(next)){names.push('引用异常');break};names.push(n.name);seen.add(next);next=n.next_id}return names.join(' → ')+(next?'':' → 直连出口')}
const configText=ref(''),jsonError=ref('')
const inspected=ref<Row|null>(null),importIndex=ref(0),importReviewed=ref(false)
async function inspectJSON(){await action(async()=>{inspected.value=await props.api('configuration/inspect','POST',{source:configText.value,format:'auto'});importIndex.value=0;importReviewed.value=false})}
async function useInspected(){const item=inspected.value?.candidates?.[importIndex.value];if(!item?.supported||!importReviewed.value)return;configText.value=JSON.stringify(item.input,null,2);await applyJSON();inspected.value=null}
watch(showForm,open=>{if(!open){configText.value='';inspected.value=null}})

function readJSON(){configText.value=JSON.stringify(Object.fromEntries(Object.entries(form.value).filter(([k])=>!['version','rotate_credentials'].includes(k))),null,2);jsonError.value=''}
async function applyJSON(){try{const parsed=JSON.parse(configText.value);if(!parsed||typeof parsed!=='object'||Array.isArray(parsed))throw new Error('需要 JSON 对象');for(const key of Object.keys(parsed)){if(!Object.hasOwn(fresh(),key))throw new Error('不支持的参数 '+key);const original=(fresh() as Row)[key],value=parsed[key];if(Array.isArray(original)?!Array.isArray(value):typeof original==='object'?(!value||typeof value!=='object'||Array.isArray(value)):typeof value!==typeof original)throw new Error('参数类型错误 '+key);if(editing.value&&['host_id','engine','kind','node_id'].includes(key)&&parsed[key]!==((form.value as Row)[key]))throw new Error('已部署协议不能切换 '+key)};const candidate={...form.value,...parsed};const t=templates.value.find(t=>t.kind===candidate.kind);const layers=t?.layers?.[candidate.engine];if(layers){const tr=candidate.transport||layers[0]?.transport;const layer=layers.find((l:Row)=>l.transport===tr);if(!layer||!layer.security_modes.includes(candidate.tls_mode||layer.security_modes[0]))throw new Error('当前内核不支持这组协议/传输/安全组合')};hydrating=true;form.value={...form.value,...parsed};await nextTick();hydrating=false;jsonError.value='';notice.value='参数已应用到表单，请保存新版本'}catch(e){hydrating=false;jsonError.value=String(e)}}
</script>
<template>
<section class="topology-workspace"><ProtocolBatch v-if="showBatch" :api="api" :hosts="hosts" :templates="templates" :certificates="certificates" :initial-host="batchHost" :initial-engine="batchEngine" @close="showBatch=false" @saved="batchSaved"/>
 <nav v-if="toolsOnly" class="topology-tabs" aria-label="高级工具"><button v-for="item in [{id:'certificates',name:'免费证书'},{id:'reverse',name:'反向代理'},{id:'catalog',name:'兼容目录'}]" :key="item.id" :class="['secondary',{active:tab===item.id}]" @click="tab=item.id">{{item.name}}</button></nav>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="notice" class="form-note" role="status">{{notice}}</p>
 <section v-if="tab==='nodes'" class="panel publish-card"><div class="section-heading"><div><span class="eyebrow">VPS CONFIGURATION</span><h2>VPS 协议配置</h2></div><div><button class="primary" :disabled="busy" @click="batch()">批量添加协议</button><button class="secondary" :disabled="busy" @click="create">添加协议</button></div></div>
 <p class="muted">选择 VPS 并配置协议即可。同一主机的入站、出站和路由会自动合并为对应内核的完整配置，由 Agent 检查并应用。</p>
 <div class="topology-tabs"><button class="secondary" :class="{active:nodeView==='inbounds'}" @click="nodeView='inbounds'">入站配置</button><button class="secondary" :class="{active:nodeView==='outbounds'}" @click="nodeView='outbounds'">出站 / 链式配置</button></div><p v-if="nodeView==='outbounds'" class="form-note">出站是当前内核访问目标时的路径，可以直连，或引用另一节点的协议端点。只引用其连接凭据和公钥信息，不向入口 Agent 发送下一跳的服务器私钥。</p><label>筛选运行主机<select v-model="hostFilter"><option value="">所有主机</option><option v-for="h in hosts" :key="h.id" :value="h.id">{{h.name}} · Agent {{h.agent_version||'未连接'}}</option></select></label>
 <details class="kernel-details"><summary>内核运行详情与完整配置</summary><div class="kernel-grid"><article v-for="h in hosts.filter(h=>!hostFilter||h.id===hostFilter)" :key="h.id" class="kernel-card"><span class="eyebrow">HOST → KERNEL → INBOUNDS</span><h3>{{h.name}}</h3><p class="muted">Agent {{h.agent_version||'未连接'}} · {{h.address}}</p><p v-if="!kernels.some(k=>k.host_id===h.id)" class="form-note">Agent 已连接也不代表内核就绪。等待 Agent 0.8+ 回报已校验的二进制。</p><div v-for="k in kernels.filter(k=>k.host_id===h.id&&['sing-box','xray'].includes(k.engine))" :key="k.engine" class="kernel-row"><div><b>{{k.engine}}</b><small class="block-muted">{{k.version}}</small><small class="block-muted">{{k.inbounds}} 入站 · 保留 {{k.revisions}} 个部署版本</small><span :class="['status',k.ready?'succeeded':'pending']">{{k.ready?'内核已就绪':'内核不可用 / 离线'}}</span><small class="block-muted">{{!k.inbounds?'尚未创建入站':k.current?k.state:'等待完整版本同步'}} {{k.desired_checksum?.slice(0,12)}}</small></div><div><button class="text-button" @click="createOn(h.id,k.engine)">添加此主机入站</button><button class="text-button" :disabled="!k.revisions" @click="showKernel(h.id,k.engine)">完整部署配置</button></div></div></article></div></details>
 <div class="table-scroll"><table><thead><tr><th>协议名称 / VPS</th><th>内核 → 协议入站</th><th>出站链路</th><th>运行状态</th><th>配置</th></tr></thead><tbody><tr v-for="s in filtered" :key="s.id"><td>{{s.name}}<small class="block-muted">{{hostName(s.host_id)}}</small></td><td>{{['frps','frpc'].includes(s.kind)?'FRP':s.engine}} → {{s.kind}}<small class="block-muted">{{s.address}} : {{s.port}}</small></td><td>{{chain(s)}}</td><td><span :class="['status',s.online?'succeeded':'pending']">{{s.delete_requested_at?'正在删除 / 等待停止':s.online?(['frps','frpc'].includes(s.kind)?'FRP 进程运行':'运行中'):s.enabled?s.state:'停用'}}</span><small class="block-muted">版本 {{s.reported_version}} / {{s.version}}</small></td><td><button class="text-button" :disabled="busy||!!s.delete_requested_at" @click="edit(s)">{{nodeView==='outbounds'?'配置出站':'详情 / 编辑'}}</button><button class="text-button" :disabled="busy||!!s.delete_requested_at" @click="toggle(s)">{{s.enabled?'停用':'启用'}}</button><button class="text-button danger" :disabled="busy||!!s.delete_requested_at" @click="remove(s)">删除</button></td></tr></tbody></table></div><p v-if="!filtered.length" class="muted">先连接主机，再选择该 VPS 添加协议配置。</p></section>
 <GatewayManager v-if="['certificates','reverse'].includes(tab)" :api="api" :view="tab" @changed="reload();emit('changed')"/>
 <section v-if="tab==='catalog'" class="panel publish-card"><span class="eyebrow">ENGINE CAPABILITIES / 2026-10-27</span><h2>内核能力与平台实现范围</h2><p class="muted">按官方文档列出入站和出站，区分“内核文档支持”与“本平台已实现”。文档中新能力可能要求不同版本或构建选项。传输层 TCP、WebSocket、gRPC、XHTTP 与 TLS、REALITY 不等于代理协议；当前编辑器开放已测试的 TCP / WebSocket / gRPC / HTTPUpgrade / XHTTP / HTTP2 / mKCP，以及 QUIC 协议的固定传输。</p><div class="table-scroll"><table><thead><tr><th>内核</th><th>协议 / 功能</th><th>入站</th><th>出站</th><th>平台模板</th></tr></thead><tbody><tr v-for="c in catalog" :key="c.engine+c.protocol"><td>{{c.engine}} {{c.pinned_version}}</td><td><a :href="c.source" target="_blank" rel="noreferrer">{{c.protocol}}</a></td><td>{{c.inbound?'有':'—'}}</td><td>{{c.outbound?'有':'—'}}</td><td>{{c.status}}</td></tr></tbody></table></div></section>
 <div v-if="showForm" class="modal-backdrop" @keydown.esc="showForm=false"><form class="modal topology-editor" role="dialog" aria-modal="true" aria-labelledby="node-editor-title" @submit.prevent="save"><div class="modal-heading"><div><span class="eyebrow">{{editing?'VERSIONED CONFIGURATION':'NEW DEPLOYMENT'}}</span><h2 id="node-editor-title">{{editing?'编辑协议配置':'添加 VPS 协议'}}</h2></div><button class="secondary" type="button" @click="showForm=false;form.private_key=''">关闭</button></div><div class="form-content"><p v-if="error" class="error">{{error}}</p><div class="fields"><label>运行主机<select v-model="form.host_id" :disabled="!!editing" required><option value="" disabled>选择主机</option><option v-for="h in hosts" :key="h.id" :value="h.id">{{h.name}}</option></select></label><label>内核<select v-model="form.engine"><option value="sing-box">sing-box · 官方版</option><option value="xray">Xray-core · 官方版</option><option v-if="!editing" value="frp">FRP 穿透</option></select></label><label>部署名称<input v-model="form.name" required maxlength="100"></label><label>入站协议<select v-model="form.kind" :disabled="!!editing"><template v-if="form.engine!=='frp'"><option v-for="t in compatible" :key="t.kind" :value="t.kind">{{t.name}}</option></template><template v-else><option value="frps">FRP 服务端</option><option value="frpc">FRP 客户端</option></template></select></label><label v-if="form.kind==='vless'&&form.transport==='tcp'">流控（可选）<select v-model="form.flow"><option value="">无</option><option value="xtls-rprx-vision">XTLS Vision</option></select></label><label v-if="form.kind==='tuic'">拥塞控制（可选）<select v-model="form.congestion"><option value="">默认 cubic</option><option>cubic</option><option>bbr</option><option>new_reno</option></select></label><label v-if="needsTLS">ALPN（可选）<input v-model="alpnText" placeholder="h2,http/1.1；TUIC 固定 h3"></label></div>
 <ProtocolLayers v-if="form.engine!=='frp'" :form="form" :template="activeTemplate"/><template v-if="isReality"><h3>REALITY 目标与客户端身份</h3><label>大厂 SNI / 握手目标候选<select aria-label="大厂 SNI 候选" @change="chooseSNI(($event.target as HTMLSelectElement).value)"><option value="">自定义 / 保留当前目标</option><option v-for="s in sniPresets" :key="s.host" :value="s.host">{{s.name}} · {{s.host}}</option></select></label><p class="form-note">无需持有目标站域名或申请其证书。目标站需支持合适的 TLS 1.3 握手，SNI 必须被目标站接受。可填写大厂站点，部署前需从该 VPS 验证其可达性和兼容性。</p><div class="fields"><label>握手目标域名（必填）<input v-model="form.reality.target" required placeholder="www.microsoft.com"></label><label>目标端口（必填）<input v-model.number="form.reality.port" type="number" min="1" max="65535" required></label><label>服务器名 SNI（必填）<input v-model="form.server_name" required placeholder="与目标站证书 SAN 相符"></label><label>Short ID（可选，留空生成）<input v-model="form.reality.short_id" placeholder="2–16 位十六进制，偶数长度"></label><label>客户端指纹<select v-model="form.reality.fingerprint"><option>chrome</option><option :disabled="form.engine==='xray'">firefox</option><option :disabled="form.engine==='xray'">safari</option><option :disabled="form.engine==='xray'">edge</option></select></label></div><p class="muted">X25519 密钥由控制端自动生成并加密保存；客户端仅收到公钥。修改 SNI 不能代替普通 TLS 的证书。</p></template>
 <p v-if="activeTemplate?.note" class="form-note">{{activeTemplate.note}}</p>
 <div v-if="form.kind==='shadowsocks'" class="fields"><label>加密方式<select v-model="form.cipher"><option value="">2022-blake3-aes-256-gcm（默认）</option><option value="2022-blake3-aes-128-gcm">2022-blake3-aes-128-gcm</option><option value="2022-blake3-chacha20-poly1305">2022-blake3-chacha20-poly1305</option><option value="aes-128-gcm">aes-128-gcm</option><option value="aes-256-gcm">aes-256-gcm</option><option value="chacha20-ietf-poly1305">chacha20-ietf-poly1305</option></select></label></div>
 <div v-if="form.kind==='snell'" class="fields"><label>Snell 模式<select v-model.number="form.snell_version" @change="form.snell_obfs='';form.snell_host='';form.snell_mode=''"><option :value="0">v4 兼容（默认）</option><option :value="5">v4 兼容 · 自定义混淆</option><option :value="6">v6 · sing-box 客户端</option></select></label><template v-if="form.snell_version!==6"><label>混淆<select v-model="form.snell_obfs" @change="form.snell_host=''"><option value="">无</option><option value="http">HTTP</option></select></label><label v-if="form.snell_obfs==='http'">混淆 Host<input v-model="form.snell_host" placeholder="bing.com（默认）"></label></template><label v-else>流量整形<select v-model="form.snell_mode"><option value="">默认加密整形</option><option value="unshaped">仅加密，不整形</option></select></label></div>
 <div v-if="form.kind==='hysteria'" class="fields"><label>Hysteria v1 混淆密码（可选）<input v-model="form.hysteria_obfs_password" type="password" autocomplete="off" placeholder="留空保留 / 新建时禁用"></label><label v-if="editing" class="check-label"><input v-model="form.clear_hysteria_obfs" type="checkbox">关闭原有 Hysteria v1 混淆</label><label>上传 Mbps（必填）<input v-model.number="form.up_mbps" type="number" min="1" max="100000" required></label><label>下载 Mbps（必填）<input v-model.number="form.down_mbps" type="number" min="1" max="100000" required></label></div><details v-if="form.kind==='hysteria2'"><summary>HY2 混淆与带宽（可选）</summary><div class="fields"><label>Salamander 密码<input v-model="form.hy2_obfs_password" type="password" autocomplete="off" :placeholder="editing?'留空保留当前密码':'留空禁用混淆'"></label><label v-if="editing" class="check-label"><input v-model="form.clear_hy2_obfs" type="checkbox">关闭已有 Salamander 混淆</label><label>上传 Mbps<input v-model.number="form.up_mbps" type="number" min="0" max="100000"></label><label>下载 Mbps<input v-model.number="form.down_mbps" type="number" min="0" max="100000"></label></div><p class="muted">0 使用内核默认带宽行为。混淆密码同步写入客户端出站配置。</p></details>
 <label v-if="!['frps','frpc'].includes(form.kind)" class="check-label"><input v-model="form.managed_users" type="checkbox">按用户 / 用户组授权并独立计量（SS 需 sing-box 2022 AES；Snell 用户身份仅限 sing-box 1.14+）</label><details><summary>自定义身份凭据（可选，默认自动生成）</summary><h3>身份凭据（只写）</h3><div class="fields"><label v-if="['http','socks','mixed','naive'].includes(form.kind)">登录用户名（留空 harbor）<input v-model="form.username" maxlength="128" autocomplete="off"></label><label v-if="!['vless','vmess'].includes(form.kind)">代理密码<input v-model="form.password" type="password" autocomplete="off" placeholder="留空随机生成 / 编辑时保留当前密码"></label><label v-if="['vless','vmess','tuic'].includes(form.kind)">UUID<input v-model="form.uuid" autocomplete="off" placeholder="留空随机生成 / 编辑时保留当前 UUID"></label></div><p class="muted">SS 2022 AES-128 使用 16 字节 Base64；其他 SS 2022 / FRP 使用 32 字节 Base64；其他密码协议使用 8–256 字节密码。VLESS / VMess 使用 UUID。已有凭据不会回显；按用户授权时用户凭据由用户管理生成。</p></details><NetworkFields v-if="!['frps','frpc'].includes(form.kind)" :host="hosts.find(h=>h.id===form.host_id)" :endpoints="form.endpoint_addresses" :egress="form.egress_families" @endpoints="v=>{form.endpoint_addresses=v;if(v.length){form.address=v[0];if(v.some(x=>x.includes(':')))form.listen='::'}}" @egress="v=>form.egress_families=v"/><h3>入站监听与分享地址</h3><div class="fields"><label>客户端连接地址<input v-model="form.address" :required="form.kind!=='frpc'" placeholder="域名、IPv4 或 IPv6"></label><label>监听地址<select v-model="form.listen"><option>127.0.0.1</option><option>::1</option><option>0.0.0.0</option><option>::</option></select></label><label>监听端口<input v-model.number="form.port" type="number" min="1024" max="65535" required></label></div><p class="muted">监听地址是主机绑定地址；客户端连接地址必须从客户端网络可达。HY2/TUIC 使用 UDP。选择 0.0.0.0 / :: 才会提供公网业务入口，管理端口保持回环监听。</p>
 <template v-if="needsTLS"><h3>TLS 与证书</h3><div class="fields"><label>受管证书<select v-model="form.certificate_id"><option value="">手动 PEM {{editing?'（留空保留当前证书）':''}}</option><option v-for="c in certificates.filter(c=>c.state==='ready')" :key="c.id" :value="c.id">{{c.domain}} · 自动续期</option></select></label><label>服务器名 SNI<input v-model="form.server_name" required placeholder="proxy.example.com"></label><template v-if="!form.certificate_id"><label>证书 fullchain PEM<textarea v-model="form.certificate" :required="!editing" autocomplete="off"></textarea></label><label>私钥 PEM<textarea v-model="form.private_key" :required="!editing" autocomplete="off"></textarea></label></template></div><button class="text-button" type="button" @click="showForm=false;tab='certificates';certForm.domain=form.server_name">前往免费一键申请证书</button></template>
 <template v-if="form.engine!=='frp'"><h3>出站与链式代理</h3><div class="fields"><label>出站方式<select v-model="form.next_id"><option value="">直接访问目标</option><option v-for="n in hops" :key="n.id" :value="n.id">下一跳：{{n.name}} · {{n.engine}} / {{n.kind}}</option></select></label><label v-if="editing" class="check-label"><input v-model="form.rotate_credentials" type="checkbox">轮换此节点代理凭据（已有客户端需更新订阅）</label></div><p class="muted">客户端 → 当前入站 → 下一跳节点 → 后续节点 → 目标。最多 8 跳，拒绝环路；下一跳凭据或证书更新后自动同步。Xray 出站仅开放已验证的 SS / VLESS / VMess / Trojan / HTTP / SOCKS 组合。</p></template>
 <template v-else><label v-if="form.kind==='frpc'">关联 FRP 服务端<select v-model="form.parent_id" required><option value="">选择服务端</option><option v-for="s in services.filter(s=>s.kind==='frps')" :key="s.id" :value="s.id">{{s.name}}</option></select></label><p class="form-note">公网 / 可达主机运行 frps；内网主机运行 frpc 并主动连接服务端，证书和令牌自动继承。TCP 映射需放行 TCP 端口，UDP 映射需放行 UDP 端口；frpc 不需公网入站管理端口。运行状态表示进程存活，隧道连通请测试目标服务。</p><button v-if="form.kind==='frps'" type="button" class="secondary" @click="form.tunnels.push({name:'tunnel-'+(form.tunnels.length+1),type:'tcp',local_host:'127.0.0.1',local_port:3000,remote_port:30000})">添加 FRP 隧道</button><div v-for="(t,i) in form.tunnels" :key="i" class="fields"><label>协议<select v-model="t.type"><option value="">TCP（默认）</option><option value="tcp">TCP</option><option value="udp">UDP</option></select></label><label>隧道名<input v-model="t.name" required></label><label>内网目标地址<select v-model="t.local_host"><option>127.0.0.1</option><option>::1</option></select></label><label>本地端口<input v-model.number="t.local_port" type="number" required></label><label>中继映射端口<input v-model.number="t.remote_port" type="number" required></label><button type="button" @click="form.tunnels.splice(i,1)">移除</button></div></template>
 <details><summary>手动编辑协议参数 JSON</summary><p class="muted">读取当前表单后编辑，再应用回表单并保存。空凭据在修改时保留；生成的完整内核配置与用户授权自动合并。</p><button type="button" class="secondary" @click="readJSON">读取当前参数</button><label>VPS 协议配置<textarea v-model="configText" class="config-preview" rows="12" spellcheck="false"></textarea></label><div class="row-actions"><button type="button" class="secondary" @click="applyJSON">应用参数 JSON 到表单</button><button type="button" class="secondary" :disabled="busy" @click="inspectJSON">识别原生 JSON / YAML</button></div><section v-if="inspected" class="panel"><p>识别格式：{{inspected.format}}</p><p v-for="(w,i) in inspected.warnings" :key="i" class="form-note">{{w}}</p><label v-if="inspected.candidates?.length">选择入站<select v-model.number="importIndex" @change="importReviewed=false"><option v-for="(c,i) in inspected.candidates" :key="i" :value="i">{{c.name||c.input.kind}} · {{c.supported?'有受控适配':'尚未适配'}}</option></select></label><p v-for="(w,i) in inspected.candidates?.[importIndex]?.warnings??[]" :key="i" class="form-note">{{w}}</p><label class="check-label"><input v-model="importReviewed" type="checkbox">已核对：仅应用可识别字段；其他字段与路由未迁移</label><button class="secondary" type="button" :disabled="!importReviewed||!inspected.candidates?.[importIndex]?.supported" @click="useInspected">应用选中入站草稿</button></section><p v-if="jsonError" class="error">{{jsonError}}</p></details>
 <details v-if="preview"><summary>查看生成的完整入站 / 出站配置（凭据已隐藏）</summary><pre class="config-preview">{{JSON.stringify(preview,null,2)}}</pre></details><p v-if="editing" class="muted">当前版本 {{form.version}}。配置保存后自动下发。主机和协议种类保持不变；FRP 修改需要先停用并确认停止。</p></div><div class="modal-footer"><button class="secondary" type="button" @click="showForm=false">取消</button><button class="primary" :disabled="busy">{{editing?'保存配置新版本':'创建并保持停用'}}</button></div></form></div>
 <div v-if="kernelPreview" class="modal-backdrop"><section class="modal topology-editor" role="dialog" aria-modal="true" aria-label="完整主机内核配置"><div class="modal-heading"><h2>{{kernelPreview.engine}} · 完整部署版本</h2><button class="secondary" @click="kernelPreview=null">关闭</button></div><div class="form-content"><p>{{kernelPreview.members}} 个入站；摘要 {{kernelPreview.checksum}}</p><pre class="config-preview">{{JSON.stringify(kernelPreview.rendered,null,2)}}</pre></div></section></div>
 <div v-if="confirm" class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="topology-confirm"><div class="modal-heading"><h2 id="topology-confirm">确认{{confirm.operation==='delete'?'删除协议':confirm.operation==='toggle'?(confirm.enabled?'停止服务':'启动真实服务'):confirm.operation==='certificate'?'申请免费证书':'保存反代设置'}}</h2></div><div class="form-content"><p>{{confirm.name}}</p><p v-if="confirm.operation==='certificate'&&certForm.provider!=='manual'">将通过 Let's Encrypt 免费签发并自动续期；使用其服务即同意当前订户协议。请确认域名控制权与验证配置。</p><p v-else-if="confirm.operation==='reverse'">启用后此域名会公开访问选定上游应用。Nginx 校验通过后才回报生效。</p><p v-else-if="confirm.operation==='delete'">将移除此协议的组权限和订阅引用。运行中服务先停止，收到 Agent 回执后自动删除；仍被链式出站或 FRP 引用时需要先解除引用。</p><p v-else>请确认监听地址及业务端口防火墙。Agent 将在下一次同步执行。</p></div><div class="modal-footer"><button class="secondary" @click="confirm=null">取消</button><button class="primary" @click="confirmAction">确认执行</button></div></section></div>
</section>
</template>
<style scoped>
.kernel-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:16px;margin:22px 0}.kernel-card{border:1px solid var(--border);border-radius:16px;padding:20px;background:var(--bg)}.kernel-card h3{margin:10px 0}.kernel-row{display:flex;justify-content:space-between;gap:12px;border-top:1px solid var(--border);padding:16px 0}.kernel-row>div:last-child{display:flex;flex-direction:column;align-items:flex-end}.topology-flow,.topology-tabs{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 20px}.topology-flow{padding:18px;border:1px solid var(--border);border-radius:14px;font-size:12px;color:var(--muted)}.topology-flow b{opacity:.4}.topology-tabs .active{border-color:var(--accent);color:var(--accent)}.topology-editor{width:min(1000px,95vw);max-height:92vh;display:flex;flex-direction:column}.topology-editor .form-content{overflow:auto}.config-preview{white-space:pre-wrap;overflow-wrap:anywhere;background:var(--bg);padding:16px;max-height:350px;overflow:auto;font-size:12px}h3{margin:24px 0 14px}.topology-workspace select{max-width:100%}@media(max-width:640px){.topology-tabs button{flex:1;min-width:42%}.topology-flow{gap:6px;padding:12px}.topology-editor{width:100vw;max-height:96dvh}.topology-editor .fields{grid-template-columns:1fr}}
</style>
